package com.minecraft.core.api.skin.library;

import com.minecraft.core.Core;
import com.minecraft.core.api.skin.Skin;
import com.minecraft.core.api.skin.objects.SkinCategory;
import com.minecraft.core.api.skin.objects.SkinCollection;
import com.minecraft.core.api.skin.objects.SkinGender;
import lombok.AllArgsConstructor;
import lombok.Getter;

import java.util.*;
import java.util.stream.Collectors;

@Getter
@AllArgsConstructor
public enum SkinLibrary {

    /* Diversas Skins */
    ANA(SkinCategory.DIVERSAS, SkinGender.FEMALE, Skin.library("Ana",
            "",
            "")),
    PALHAÇO(SkinCategory.DIVERSAS, SkinGender.MAN, Skin.library("Palhaço",
            "",
            "")),
    CHRISTIAN(SkinCategory.DIVERSAS, SkinGender.MAN, Skin.library("Christian",
            "",
            "")),
    LUCKY(SkinCategory.DIVERSAS, SkinGender.MAN, Skin.library("Lucky",
            "",
            "")),
    JANE(SkinCategory.DIVERSAS, SkinGender.FEMALE, Skin.library("Jane",
            "",
            "")),
    LUCY(SkinCategory.DIVERSAS, SkinGender.FEMALE, Skin.library("Lucy",
            "",
            "")),
    ALENNE(SkinCategory.DIVERSAS, SkinGender.FEMALE, Skin.library("Alenne",
            "",
            "")),

    /* Super-heróis Skins */
    HOMEM_ARANHA(SkinCategory.SUPER_HEROES, SkinGender.MAN, Skin.library("Homem-Aranha",
            "",
            "")),
    SUPERMAN(SkinCategory.SUPER_HEROES, SkinGender.MAN, Skin.library("Super Homem",
            "",
            "")),

    /* Games skins */
    SUPER_MARIO(SkinCategory.JOGOS, SkinGender.MAN, Skin.library("Alenne",
            "",
                    ""));



    private final SkinCategory category;
    private final SkinGender gender;
    private final Skin skin;

    private final static List<SkinLibrary> list = new ArrayList<>(Arrays.asList(values()));

    public static Skin of(String name) {
        return list.stream()
                .filter(skin -> skin.getSkin().getDisplayName().equalsIgnoreCase(name))
                .findFirst()
                .map(SkinLibrary::getSkin)
                .orElse(null);
    }

    public static List<Skin> getSkins() {
        return list.stream().map(SkinLibrary::getSkin).collect(Collectors.toList());
    }

    public static List<SkinLibrary> getLibrarySkins(SkinCategory category) {
        return list.stream()
                .filter(skin -> skin.getCategory().equals(category))
                .collect(Collectors.toList());
    }

    public static List<Skin> getSkins(SkinCategory category) {
        if (category.equals(SkinCategory.NONE)) return getSkins();

        return list.stream()
                .filter(skin -> skin.getCategory().equals(category))
                .map(SkinLibrary::getSkin)
                .collect(Collectors.toList());
    }

    public static Skin random() {
        return values()[Core.RANDOM.nextInt(values().length)].getSkin();
    }
    private static final Map<SkinLibrary, List<SkinVariation>> VARIATIONS_MAP = new HashMap<>();

    static {
        VARIATIONS_MAP.put(HOMEM_ARANHA, Arrays.asList(
            new SkinVariation("Padrão",
                    "",
                    ""),
            new SkinVariation("Uniforme Preto",
                "",
                ""),
            new SkinVariation("Sem máscara",
                "",
                ""),
            new SkinVariation("Miles Morales",
                "",
                ""),
            new SkinVariation("Azul e Vermelho",
                "",
                "")

        ));
        VARIATIONS_MAP.put(SUPERMAN, Arrays.asList(
                new SkinVariation("Padrão",
                        "",
                        ""),
                new SkinVariation("Super mulher",
                        "",
                        ""),
                new SkinVariation("Sem uniforme",
                        "",
                        "")
        ));
    }

    public static List<SkinVariation> getVariations(SkinLibrary skinLibrary) {
        return VARIATIONS_MAP.getOrDefault(skinLibrary, Collections.emptyList());
    }

    public static boolean hasVariations(SkinLibrary skinLibrary) {
        List<SkinVariation> variations = VARIATIONS_MAP.get(skinLibrary);
        return variations != null && !variations.isEmpty();
    }

    @Getter
    @AllArgsConstructor
    public static class SkinVariation {
        private final String name;
        private final String value;
        private final String signature;

        public Skin toSkin(String baseName) {
            return Skin.library(baseName + " - " + name, value, signature);
        }
    }
}
